#!/bin/sh
# /etc/lava-server is a Docker volume with persistent_db, and a volume
# hides what the image put there after its first start: install the
# settings.conf generated by lavalab-gen before LAVA's entrypoint (which
# runs the database setup and migrations with it) starts.
install -o lavaserver -g lavaserver -m 0640 /root/settings.conf /etc/lava-server/settings.conf || exit $?
exec /root/entrypoint.sh "$@"
